package psx.exporter;
import java.lang.classfile.*;import java.lang.classfile.instruction.*;import java.util.*;
/** Independent current physical status cache. The original unheated-probe
 * autothrottle disconnect tail continues; no ice/fault method is suppressed. */
final class FmcReconstructionIceEffects {
    static final FmcQualification.Member STATUS=new FmcQualification.Member("Ice","allHeated","Z");
    private static final Prepare.MethodId CHECK=new Prepare.MethodId("Ice","checkAllHeated","()V");
    static Set<FmcQualification.Member> inspect(Prepare data,Set<FmcQualification.Member> construction,Set<FmcQualification.Member> currentInputs){
        if(construction.contains(STATUS)||currentInputs.contains(STATUS))throw new IllegalArgumentException("heater status overlaps reconstruction/current input");
        if(!FmcReconstructionPageEffects.writers(data,Set.of(STATUS)).getOrDefault(STATUS,Set.of()).equals(Set.of(CHECK,new Prepare.MethodId("Ice","situLoadInit","()V")))||!FmcReconstructionExecAudit.inspect(data).writers().getOrDefault(STATUS,Set.of()).equals(Set.of(CHECK)))throw new IllegalArgumentException("native heater status writer drift");
        var method=data.methods.get(CHECK);var ops=Prepare.instructions(method);String[] heaters={"eaTatL","eaTatR","eaPitotL","eaPitotR","eaAuxL","eaAuxR","eaIndL","eaIndR","eaAoaL","eaAoaR"};
        var labels=new HashMap<Label,Integer>();int ordinal=0;for(var e:method.code().orElseThrow()){if(e instanceof LabelTarget l)labels.put(l.label(),ordinal);if(e instanceof Instruction)ordinal++;}
        if(ops.size()!=44)throw new IllegalArgumentException("native heater status exact instruction shape");
        for(int i=0;i<10;i++)if(!Prepare.field(ops.get(i*3),Opcode.GETSTATIC,"Ice",heaters[i])||!(ops.get(i*3) instanceof FieldInstruction reference)||!reference.type().equalsString("LElecAdapter;")||!Prepare.field(ops.get(i*3+1),Opcode.GETFIELD,"ElecAdapter","isPowered")||!(ops.get(i*3+1) instanceof FieldInstruction powered)||!powered.type().equalsString("Z")||!(ops.get(i*3+2) instanceof BranchInstruction branch)||branch.opcode()!=Opcode.IFEQ||labels.get(branch.target())!=32)throw new IllegalArgumentException("native heater prefix input/short circuit drift "+heaters[i]);
        if(ops.get(30).opcode()!=Opcode.ICONST_1||!(ops.get(31) instanceof BranchInstruction done)||done.opcode()!=Opcode.GOTO||labels.get(done.target())!=33||ops.get(32).opcode()!=Opcode.ICONST_0||!Prepare.field(ops.get(33),Opcode.PUTSTATIC,"Ice","allHeated"))throw new IllegalArgumentException("native heater single boolean publication drift");
        // Exact existing fault continuation after the status publication.
        if(!Prepare.field(ops.get(34),Opcode.GETSTATIC,"Ice","allHeated")||!(ops.get(35) instanceof BranchInstruction heated)||heated.opcode()!=Opcode.IFNE||labels.get(heated.target())!=43||!Prepare.field(ops.get(36),Opcode.GETSTATIC,"Core","situLoadedTime")||ops.get(37).opcode()!=Opcode.ICONST_1||!(ops.get(38) instanceof BranchInstruction loaded)||loaded.opcode()!=Opcode.IF_ICMPLE||labels.get(loaded.target())!=43||!Prepare.field(ops.get(39),Opcode.GETSTATIC,"AfdsHub","throttleMode")||!(ops.get(40) instanceof BranchInstruction inactive)||inactive.opcode()!=Opcode.IFEQ||labels.get(inactive.target())!=43||ops.get(41).opcode()!=Opcode.ICONST_1||!(ops.get(42) instanceof InvokeInstruction disconnect)||disconnect.opcode()!=Opcode.INVOKESTATIC||!disconnect.owner().asInternalName().equals("AfdsHub")||!disconnect.name().equalsString("disconnectAutothrottle")||!disconnect.type().equalsString("(Z)V")||ops.get(43).opcode()!=Opcode.RETURN)throw new IllegalArgumentException("native unheated autothrottle fault tail drift");
        for(var group:List.of(FmcNarrowContent.HEADER_INPUTS,FmcNarrowContent.PERF_INPUTS,FmcNarrowContent.WAYPOINT_INPUTS))for(var input:group)if(STATUS.equals(new FmcQualification.Member(input.owner(),input.name(),input.descriptor())))throw new IllegalArgumentException("heater status cannot be artifact input");return Set.of(STATUS);
    }
    static FmcReconstructionNormalExec.Profile apply(Prepare data,FmcReconstructionNormalExec.Profile normal,Set<FmcQualification.Member> construction,Set<FmcQualification.Member> currentInputs){var fields=new HashSet<>(normal.fields());fields.addAll(inspect(data,construction,currentInputs));return new FmcReconstructionNormalExec.Profile(Set.copyOf(fields),normal.banks(),normal.retainedInputs(),normal.bankReaders(),normal.references(),normal.dynamicScratchpads(),normal.atomicCurrentOutputs());}
}
